function freeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const nested of Object.values(value)) freeze(nested);
    Object.freeze(value);
  }
  return value;
}

function fixture({
  visualId,
  type,
  topology,
  labels = [],
  states = [],
  values = [],
  requiredEdges = [],
  requiredBranches = [],
  edgeLabelTruths = [],
  structure,
}) {
  return {
    visualId,
    type,
    topology,
    criticalLabels: labels,
    criticalStates: states,
    criticalValues: values,
    requiredEdges,
    requiredBranches,
    edgeLabelTruths,
    structure,
  };
}

